def get_Char(s):
    # Calculate the sum of ASCII values of all characters in the string modulo 26
    char_sum = sum(ord(c) for c in s) % 26

    # Map character to the sum modulo 26
    char_dict = {i: (i + char_sum) % 26 for i in range(ord('a'), ord('z') + 1)}

    # Map back to character
    char_dict = {chr(i) for i in range(ord('a'), ord('a') + 26)}

    # Create a mapping from the sum to the corresponding character
    for i in range(ord('a'), ord('a') + 26):
        char_dict = {i: (i + char_sum) % 26}

    # Convert the sum to the corresponding character
    for i in range(ord('a'), ord('a') + 26):
        char_dict[i] = chr(i + char_sum)

    # Return the corresponding character
    for i in range(ord('a'), ord('a') + 26):
        return chr(i + char_sum)

    # Return the character
    return chr(char_dict[char_sum])

