To determine whether a given square matrix is a magic square, the matrix must meet the condition that the sum of its elements in any row, any column, and both diagonals are the same.

Here is the Python function to calculate whether the matrix is a magic square:

```python
def magic_square_test(matrix):
    def is_magic_square(n, m):
        # Calculate the sum of a row, a column, or a diagonal
        sum_row = sum(matrix[0][i] for i in range(n))
        sum_col = sum(matrix[i][0] for i in range(n))
        sum_diag1 = sum(matrix[i][i] for i in range(n))
        sum_diag2 = sum(matrix[i][n - 1 - i] for i in range(n))

        # Calculate the sum of a row, a column, and both diagonals
        row_sum = [sum_row] * n
        col_sum = [sum_col for i in range(n)]
        diag1_sum = [sum_diag1] * n
        diag2_sum = [sum_diag2] * n

        # Check if all rows, columns, and diagonals have the same sum
        for i in range(n):
            if sum_row != sum_col[i] or sum_row != sum_diag1[i] or sum_row != sum_diag2[i]:
                return False

        # Check if all rows and columns have the same sum
        for i in range(n):
            for j in range(n):
                if sum_row[i] != sum_col[i] or sum_row[i] != sum_diag1[i] or sum_row[i] != sum_diag2[i]:
                    return False
        return True
    n = len(matrix)
    m = len(matrix[0])
    if n != m or m != n:
        return False
    return is_magic_square(n, m)
