def max_product(arr):
    """
    Find the maximum product formed by multiplying numbers of an increasing subsequence of that array.

    :param arr: List[int] containing the array
    """
    if not arr:
        return 0

    # Initialize the list with 1s
    dp = [1] * len(arr)
    # dp[i] will store the maximum product of the increasing subsequence ending at i
    for i in range(len(arr)):
        for j in range(i):
            if arr[i] > arr[j] and dp[i] < dp[j] * arr[i]:
                dp[i] = dp[j] * arr[i]

    # Return the maximum product
    return max([arr[i] for i in range(len(arr))] + [max(dp)])

